:root {
  /* Primitives */
  --nw-white: #ffffff;
  --nw-blue-600: #1f5ae0;
  --nw-blue-700: #1848b8;
  --nw-teal-600: #0d9488;
  --nw-teal-700: #0f766e;
  --nw-font-inter: Inter, system-ui, sans-serif;
  --nw-font-georgia: Georgia, 'Times New Roman', serif;

  /* Brand tier: Northwind is the default */
  --nw-brand-600: var(--nw-blue-600);
  --nw-brand-700: var(--nw-blue-700);
  --nw-brand-font-heading: var(--nw-font-inter);
  --nw-brand-radius-control: 6px;
}

/* Semantic tier */
:root {
  --nw-color-action-bg: var(--nw-brand-600);
  --nw-color-action-text: var(--nw-white);
  --nw-font-heading: var(--nw-brand-font-heading);
  --nw-radius-control: var(--nw-brand-radius-control);
}

/* Add the Tidewater brand here */

/* Components: brand-agnostic, don't change */
.nw-heading { font-family: var(--nw-font-heading); margin: 0 0 12px; }
.nw-button {
  --nw-button-bg: var(--nw-color-action-bg);
  --nw-button-text: var(--nw-color-action-text);
  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  border: 0;
  border-radius: var(--nw-radius-control);
  padding: 8px 16px;
  font: inherit;
}
.compare { display: grid; gap: 24px; }

